import json,hashlib
from pathlib import Path
O=Path(__file__).resolve().parent.parent;R=O/'independent_review';B=O.parent.parent;P=B/'inputs/M2'
f=lambda p:json.loads(p.read_text())
checks=f(R/'final_record_checks.json');target=f(R/'final_targeted_checks.json');artifact=f(R/'final_artifact_inspection.json');initial=f(R/'initial_review.json')
