md=['# M2 independent final review — LIMITED','',f'Reviewer: `gpt-6-astra`  \nScene SHA256: `{hash_now}`','',review['summary'],'','No technical corruption, absent required artifact or evidence of unauthorized input was found. Review is complete. Candidate can proceed to limited-quality evaluation after the coordinator checks the exact hash; this is not a high-fidelity approval.','', '## Initial issue resolution','', '| Issue | Resolution | Evidence |','|---|---|---|']
